// holdSource is a succeedSrc whose Match blocks until the test releases it —
// the deterministic mid-drain suspension point for the parity check. entered
// closes exactly once, when Match begins.
type holdSource struct {
	succeedSrc
	entered chan struct{}
	release chan struct{}
	once    sync.Once
}

func newHoldSource(id string) *holdSource {
	return &holdSource{
		succeedSrc: succeedSrc{id: id},
		entered:    make(chan struct{}),
		release:    make(chan struct{}),
	}
}

func (h *holdSource) Match(ctx context.Context, req *metadatav1.MatchRequest) (*metadatav1.MatchResult, error) {
	h.once.Do(func() { close(h.entered) })
	<-h.release
	return h.succeedSrc.Match(ctx, req)
}

// TestSettleGateParity pins the drain/settle contract (plugin-title-enrichment
// spec scenario 2ba564501bad907f): the ONE gate resolution taken at claim
// drives BOTH driveSources (drain) and allSourcesTerminal (settle), so a pref
// flip landing mid-pass cannot split the verdict — it takes effect on the next
// pass. A gated source drains nothing and never blocks settlement; a
// source unavailable at drain stays terminal; with no gates the pass behaves
// exactly as before the threading.
func TestSettleGateParity(t *testing.T) {
	ctx := context.Background()

	t.Run("gated_source_drains_nothing_and_settles_ready", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		putItem(t, s, "i_gate", libID, statusPending, baseDoc("Show/S01E01.mkv"))
		parser := &succeedSrc{id: "tv-parser"}
		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
		q.resolve = mapResolver{"tv-parser": parser, "tmdb": &succeedSrc{id: "tmdb"}}.resolver()
		if err := s.UpsertMetadataSourcePref(ctx, store.MetadataSourcePref{
			ModuleID: "tv", PluginID: "tv-parser", Enabled: false,
		}); err != nil {
			t.Fatalf("UpsertMetadataSourcePref: %v", err)
		}

		q.workItem(ctx, "i_gate")

		it, err := s.GetItem(ctx, "i_gate")
		if err != nil {
			t.Fatalf("GetItem: %v", err)
		}
		// The gated source is non-queueable at settle: the row reaches ready
		// without any namespace from it (settle uses the claim-time resolution).
		if it.Status != statusReady {
			t.Fatalf("status = %q, want ready (gated source must not stall settlement)", it.Status)
		}
		if calls := atomic.LoadInt32(&parser.calls); calls != 0 {
			t.Fatalf("gated tv-parser drained %d Match calls, want 0", calls)
		}
		doc := decodeDoc(it.Document)
		if !hasNamespace(doc, "tmdb") {
			t.Fatalf("nongated tmdb lost its namespace (gate leaked): %v", doc)
		}
		if hasNamespace(doc, "tv-parser") {
			t.Fatalf("gated tv-parser wrote a namespace: %v", doc)
		}
	})

	// The discriminator: tmdb is disabled at claim, the pref flips to enabled
	// while the chain source holds mid-drain. The claim-time resolution must
	// govern BOTH the drain decision (tmdb's binding copy stays Enabled=false,
	// so the drain skips it) AND the settle verdict (non-queueable -> ready).
	// A settle that re-resolved independently would see tmdb queueable with no
	// namespace and stall the row at enriched — the split verdict this box
	// forbids.
	t.Run("mid_pass_enable_flip_does_not_split_verdict", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		putItem(t, s, "i_flip", libID, statusPending, baseDoc("Show/S01E01.mkv"))
		parser := newHoldSource("tv-parser")
		tmdb := &succeedSrc{id: "tmdb"}
		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
		q.resolve = mapResolver{"tv-parser": parser, "tmdb": tmdb}.resolver()
		if err := s.UpsertMetadataSourcePref(ctx, store.MetadataSourcePref{
			ModuleID: "tv", PluginID: "tmdb", Enabled: false,
		}); err != nil {
			t.Fatalf("UpsertMetadataSourcePref: %v", err)
		}

		done := make(chan struct{})
		go func() {
			defer close(done)
			q.workItem(ctx, "i_flip")
		}()
		select {
		case <-parser.entered: // drain in progress — the claim resolution is taken
		case <-time.After(3 * time.Second):
			close(parser.release)
			t.Fatal("tv-parser never entered Match (drain never started)")
		}
		// The flip lands mid-pass, BEFORE the drain reaches tmdb's slot.
		if err := s.UpsertMetadataSourcePref(ctx, store.MetadataSourcePref{
			ModuleID: "tv", PluginID: "tmdb", Enabled: true,
		}); err != nil {
			t.Fatalf("UpsertMetadataSourcePref (mid-pass flip): %v", err)
		}
		close(parser.release)
		<-done

		it, err := s.GetItem(ctx, "i_flip")
		if err != nil {
			t.Fatalf("GetItem: %v", err)
		}
		if it.Status != statusReady {
			t.Fatalf("status = %q, want ready (settle must hold the claim-time resolution, not re-resolve)", it.Status)
		}
		if calls := atomic.LoadInt32(&tmdb.calls); calls != 0 {
			t.Fatalf("mid-pass enabled tmdb drained %d Match calls this pass, want 0 (next pass catches it)", calls)
		}
		if doc := decodeDoc(it.Document); hasNamespace(doc, "tmdb") {
			t.Fatalf("mid-pass enabled tmdb wrote a namespace this pass: %v", doc)
		}
	})

	t.Run("unavailable_surviving_source_settles_ready", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		putItem(t, s, "i_un", libID, statusPending, baseDoc("Show/S01E01.mkv"))
		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
		// tmdb is not loaded: the drain records an unavailable stage for it, and
		// the settle must count that attempt as terminal (attemptedNoWork).
		q.resolve = mapResolver{"tv-parser": &succeedSrc{id: "tv-parser"}}.resolver()

		q.workItem(ctx, "i_un")

		it, err := s.GetItem(ctx, "i_un")
		if err != nil {
			t.Fatalf("GetItem: %v", err)
		}
		if it.Status != statusReady {
			t.Fatalf("status = %q, want ready (unavailable source is terminal at settle)", it.Status)
		}
		if doc := decodeDoc(it.Document); !hasNamespace(doc, "tv-parser") {
			t.Fatalf("tv-parser lost its namespace: %v", doc)
		}
	})

	t.Run("nongated_pass_byte_identical", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		putItem(t, s, "i_plain", libID, statusPending, baseDoc("Show/S01E01.mkv"))
		parser := &succeedSrc{id: "tv-parser"}
		tmdb := &succeedSrc{id: "tmdb"}
		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
		q.resolve = mapResolver{"tv-parser": parser, "tmdb": tmdb}.resolver()

		q.workItem(ctx, "i_plain")

		it, err := s.GetItem(ctx, "i_plain")
		if err != nil {
			t.Fatalf("GetItem: %v", err)
		}
		if it.Status != statusReady {
			t.Fatalf("status = %q, want ready", it.Status)
		}
		if calls := atomic.LoadInt32(&parser.calls); calls != 1 {
			t.Fatalf("tv-parser Match calls = %d, want 1", calls)
		}
		if calls := atomic.LoadInt32(&tmdb.calls); calls != 1 {
			t.Fatalf("tmdb Match calls = %d, want 1", calls)
		}
		doc := decodeDoc(it.Document)
		if !hasNamespace(doc, "tv-parser") || !hasNamespace(doc, "tmdb") {
			t.Fatalf("nongated pass lost a namespace: %v", doc)
		}
	})
}
